import json,redis,sys
from urllib.parse import urlsplit
from app.tasks.celery_app import celery_app
u=urlsplit(celery_app.conf.broker_url)
assert u.hostname=='127.0.0.1' and u.port==17124 and u.path=='/1', 'wrong actual broker'
b=urlsplit(celery_app.conf.result_backend)
assert b.hostname=='127.0.0.1' and b.port==17124 and b.path=='/2', 'wrong actual result backend'
if sys.argv[1]=='workers':
    i=celery_app.control.inspect(timeout=5)
    d={k:getattr(i,k)() for k in ['active','reserved','scheduled']}
else:
    d={}
r=redis.Redis.from_url(celery_app.conf.broker_url)
d['actualBroker']={'host':u.hostname,'port':u.port,'db':u.path,'resultDb':b.path}
d['redis']={'role':r.info('replication')['role'],'runId':r.info('server')['run_id'],'dbsize':r.dbsize(),'brokerLists':{k.decode():r.llen(k) for k in r.scan_iter() if r.type(k)==b'list' and (k.startswith(b'default') or k.startswith(b'dead_letter'))},'unacked':r.hlen('unacked'),'unackedIndex':r.zcard('unacked_index')}
print(json.dumps(d))
